param([ValidateSet('Debug','Release')][string]$Config='Debug',[switch]$Tools,[switch]$NoDeploy,[ValidateSet('SYNC_RhythmShooter','SYNC_RhythmBall','SYNC_RhythmBreakout','SYNC_RhythmBombAction','SYNC_RhythmMining','SYNC_RhythmTrain','SYNC_RhythmNaval')][string]$ProjectName='SYNC_RhythmShooter')
$ErrorActionPreference='Stop'
$toolScript=switch($ProjectName){'SYNC_RhythmBall'{'BuildBallTools.cmd'}'SYNC_RhythmBreakout'{'BuildBreakoutTools.cmd'}'SYNC_RhythmBombAction'{'BuildBombActionTools.cmd'}'SYNC_RhythmMining'{'BuildMiningTools.cmd'}'SYNC_RhythmTrain'{'BuildTrainTools.cmd'}'SYNC_RhythmNaval'{'BuildNavalTools.cmd'}default{'BuildTools.cmd'}}
$buildScript=switch($ProjectName){'SYNC_RhythmBall'{'BuildBall.cmd'}'SYNC_RhythmBreakout'{'BuildBreakout.cmd'}'SYNC_RhythmBombAction'{'BuildBombAction.cmd'}'SYNC_RhythmMining'{'BuildMining.cmd'}'SYNC_RhythmTrain'{'BuildTrain.cmd'}'SYNC_RhythmNaval'{'BuildNaval.cmd'}default{'Build.cmd'}}
if($Tools){ if($NoDeploy){ & $env:ComSpec /d /c (Join-Path $PSScriptRoot 'BuildPreview.cmd') $ProjectName $Config Local } else { & $env:ComSpec /d /c (Join-Path $PSScriptRoot $toolScript) $Config };if($LASTEXITCODE -ne 0){throw "Tools build failed ($LASTEXITCODE)"} }
if($NoDeploy){ & $env:ComSpec /d /c (Join-Path $PSScriptRoot 'BuildLocal.cmd') $ProjectName $Config } else { & $env:ComSpec /d /c (Join-Path $PSScriptRoot $buildScript) $Config }
if($LASTEXITCODE -ne 0){throw "Plugin build failed ($LASTEXITCODE)"}
